        return [row[:] for row in grid]

    marker = min(other, key=lambda v: (counts[v], v))
    coords_all = [(r, c) for r in range(H) for c in range(W)
                  if grid[r][c] != background]

    # Each connected colored fragment is a movable polyomino. Ignore the
    # sparse marker color.
    seen = set()
    pieces = []
    color_counts = Counter()
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (background, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                color = grid[y][x]
                cells.append((y, x, color))
                color_counts[color] += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < H and 0 <= nx < W and
                            (ny, nx) not in seen and
                            grid[ny][nx] not in (background, marker)):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            mr = min(y for y, x, v in cells)
            mc = min(x for y, x, v in cells)
            pieces.append(tuple(sorted((y - mr, x - mc, v)
                                       for y, x, v in cells)))

    if not pieces:
        return [row[:] for row in grid]

    edge_color = max(color_counts, key=color_counts.get)
    total_area = sum(len(p) for p in pieces)

    dimensions = []
    for h in range(1, min(H, total_area) + 1):
        if total_area % h == 0:
            w = total_area // h
            if w <= W:
                dimensions.append((h, w))
    dimensions.sort(key=lambda d: (abs(d[0] - d[1]), d[0] > d[1]))

    def shape_orientations(piece, rotate, reflect):
        out = []
        mirror_options = (False, True) if reflect else (False,)
        for mirror in mirror_options:
            points = [(y, -x if mirror else x, v) for y, x, v in piece]
            turns = 4 if rotate else 1
            cur = points
            for _ in range(turns):
                mr = min(y for y, x, v in cur)
                mc = min(x for y, x, v in cur)
                shape = tuple(sorted((y - mr, x - mc, v)
                                     for y, x, v in cur))
                if shape not in out:
                    out.append(shape)
                cur = [(x, -y, v) for y, x, v in cur]
        return out

    def tile(height, width, rotate, reflect, match_seams, border,
             node_limit):
        n = len(pieces)
        size = height * width
        full = (1 << size) - 1
        areas = [len(p) for p in pieces]

        neighbors = [[] for _ in range(size)]
        for y in range(height):
            for x in range(width):
                i = y * width + x
                if y:
                    neighbors[i].append(i - width)
                if y + 1 < height:
                    neighbors[i].append(i + width)
                if x:
                    neighbors[i].append(i - 1)
                if x + 1 < width:
                    neighbors[i].append(i + 1)

        covers = [[] for _ in range(size)]
        by_piece = [[] for _ in range(n)]

        for pid, piece in enumerate(pieces):
            unique = set()
            for shape in shape_orientations(piece, rotate, reflect):
                ph = max(y for y, x, v in shape) + 1
                pw = max(x for y, x, v in shape) + 1
                if ph > height or pw > width:
                    continue
                for top in range(height - ph + 1):
                    for left in range(width - pw + 1):
                        cells = tuple(sorted(
                            ((top + y) * width + left + x, color)
                            for y, x, color in shape
                        ))
                        if cells in unique:
                            continue
                        unique.add(cells)

                        mask = 0
                        valid = True
                        for i, color in cells:
                            mask |= 1 << i
                            y, x = divmod(i, width)
                            if (border and
                                    (y == 0 or y == height - 1 or
                                     x == 0 or x == width - 1) and
                                    color != edge_color):
                                valid = False
                                break
                        if not valid:
                            continue

