                                        break
                                boundary[nb] = color
                                if (match_seams and border and
                                        (ny == 0 or ny == height - 1 or
                                         nx == 0 or nx == width - 1) and
                                        color != edge_color):
                                    valid = False
                                    break
                            if not valid:
                                break
                        if not valid:
                            continue

                        place = (pid, mask, cells, tuple(boundary.items()),
                                 top, left)
                        by_piece[pid].append(place)
                        for i, color in cells:
                            covers[i].append(place)

        if any(not entries for entries in covers):
            return None

        cell_order = sorted(range(size), key=lambda i: len(covers[i]))
        values = [-1] * size
        nodes = 0
        stopped = False

        subset_sum = [0] * (1 << n)
        for m in range(1, 1 << n):
            bit = m & -m
            pid = bit.bit_length() - 1
            subset_sum[m] = subset_sum[m ^ bit] + areas[pid]

        partition_cache = {}

        def regions_fit(occupied, used):
            available = ((1 << n) - 1) ^ used
            unseen = full ^ occupied
            sizes = []
            while unseen:
                first = unseen & -unseen
                unseen ^= first
                stack = [first.bit_length() - 1]
                count = 1
                while stack:
                    i = stack.pop()
                    for nb in neighbors[i]:
                        bit = 1 << nb
                        if unseen & bit:
                            unseen ^= bit
                            count += 1
                            stack.append(nb)
                sizes.append(count)

            if sum(sizes) != sum(areas[p] for p in range(n)
                                 if (available >> p) & 1):
                return False
            sizes = tuple(sorted(sizes, reverse=True))
            key = (sizes, available)
            if key in partition_cache:
                return partition_cache[key]

            memo = {}

            def assign(k, remaining):
                key2 = (k, remaining)
                if key2 in memo:
                    return memo[key2]
                if k == len(sizes):
                    answer = remaining == 0
                    memo[key2] = answer
                    return answer
                target = sizes[k]
                sub = remaining
                while sub:
                    if subset_sum[sub] == target and assign(k + 1, remaining ^ sub):
                        memo[key2] = True
                        return True
                    sub = (sub - 1) & remaining
                memo[key2] = False
                return False

            answer = assign(0, available)
            partition_cache[key] = answer
            return answer

        def compatible(place, occupied, used):
            pid, mask, cells, boundary, top, left = place
            if (used >> pid) & 1 or (mask & occupied):
                return None
            contacts = 0
            for nb, required_color in boundary:
                if (occupied >> nb) & 1:
                    contacts += 1
                    if match_seams and values[nb] != required_color:
                        return None
            return contacts

        def search(occupied, used, depth):
            nonlocal nodes, stopped
            nodes += 1
            if nodes > node_limit:
                stopped = True
                return None
            if depth == n:
                return values[:] if occupied == full else None
            if depth and not regions_fit(occupied, used):
                return None

            best_kind = "cell"
            best_id = None
            best_count = 10**9

            # Choose the most constrained uncovered cell.
            for i in cell_order:
                if (occupied >> i) & 1:
                    continue
                count = 0
                for place in covers[i]:
                    if compatible(place, occupied, used) is not None:
                        count += 1
                        if count >= best_count:
                            break
                if count == 0:
                    return None
                if count < best_count:
                    best_count = count
                    best_id = i
                    best_kind = "cell"
                    if count == 1:
                        break

            # Occasionally a remaining piece is the tighter constraint.
            if best_count > 1 and depth >= 1:
                for pid in range(n):
                    if (used >> pid) & 1:
                        continue
                    count = 0
                    for place in by_piece[pid]:
                        if compatible(place, occupied, used) is not None:
                            count += 1
                            if count >= best_count:
                                break
                    if count == 0:
                        return None
                    if count < best_count:
                        best_count = count
                        best_id = pid
                        best_kind = "piece"
                        if count == 1:
                            break

            source = covers[best_id] if best_kind == "cell" else by_piece[best_id]
            options = []
            for place in source:
                contacts = compatible(place, occupied, used)
                if contacts is not None:
                    options.append((contacts, place))
            options.sort(key=lambda item: (
                -item[0], item[1][0], item[1][4], item[1][5]
            ))

            for _, place in options:
                pid, mask, cells = place[:3]
                for i, color in cells:
                    values[i] = color
                answer = search(occupied | mask, used | (1 << pid), depth + 1)
                if answer is not None:
                    return answer
                for i, color in cells:
                    values[i] = -1
                if stopped:
                    return None
            return None

        return search(0, 0, 0)

    solution = None
    chosen = None
    modes = [
        (False, False, True, True),
        (True,  False, True, True),
        (False, True,  True, True),
        (True,  True,  True, True),
        (False, False, True, False),
        (True,  False, True, False),
        (False, True,  False, True),
        (True,  True,  False, True),
        (False, False, False, False),
        (True,  False, False, False),
    ]

    for rotate, reflect, match_seams, border in modes:
        for h, w in dimensions:
            solution = tile(h, w, rotate, reflect, match_seams, border, 350000)
            if solution is not None:
                chosen = (h, w)
                break
        if solution is not None:
            break

    if solution is None:
        return [row[:] for row in grid]

    h, w = chosen
    minr = min(r for r, c in coords_all)
    maxr = max(r for r, c in coords_all)
    minc = min(c for r, c in coords_all)
    maxc = max(c for r, c in coords_all)
    top = max(0, min(H - h, (minr + maxr - h + 1) // 2))
    left = max(0, min(W - w, (minc + maxc - w + 1) // 2))

    out = [[background for _ in range(W)] for _ in range(H)]
    for i, color in enumerate(solution):
        out[top + i // w][left + i % w] = color
